cypress_script:
describe('Todo List CRUD Operations', () => {
  it('should add a new todo item successfully', () => {
    cy.visit('https://todomvc.com/examples/react/dist/');
    cy.get('[aria-label="New Todo Input"]').type('New Todo{enter}');
    cy.get('[data-testid="todo-list"]').children().should('have.length', 1);
  });

  it('should not change the URL when trying to add an empty todo', () => {
    cy.visit('https://todomvc.com/examples/react/dist/');
    cy.get('[aria-label="New Todo Input"]').type('{enter}');
    cy.url().should('eq', 'https://todomvc.com/examples/react/dist/');
    cy.get('[data-testid="todo-list"]').children().should('have.length', 0);
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Todo List CRUD Operations', () => {
  test('should add a new todo item successfully', async ({ page }) => {
    await page.goto('https://todomvc.com/examples/react/dist/');
    await page.fill('[aria-label="New Todo Input"]', 'New Todo');
    await page.keyboard.press('Enter');
    const todoList = await page.locator('[data-testid="todo-list"]').locator('li');
    await expect(todoList).toHaveCount(1);
  });

  test('should not change the URL when trying to add an empty todo', async ({ page }) => {
    await page.goto('https://todomvc.com/examples/react/dist/');
    await page.fill('[aria-label="New Todo Input"]', '');
    await page.keyboard.press('Enter');
    await expect(page).toHaveURL('https://todomvc.com/examples/react/dist/');
    const todoList = await page.locator('[data-testid="todo-list"]').locator('li');
    await expect(todoList).toHaveCount(0);
  });
});
